import { useMemo } from 'react';

import {
  CLARA_CONSUMER_PROJECT_KEY,
  CLARA_DOMAIN_OPTIONS,
  CLARA_VALUE_CREATION_PROJECT_KEY,
} from 'components/ai/constants';
import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle, useMultiplesFeatureToggles } from 'hooks';

export function useClaraDomainToggles() {
  const [domainDropdownToggle, isDomainDropdownToggleLoading] =
    useFeatureToggle(featureToggles.aiChat.domain_dropdown);
  const {
    featuresListByToggleName: domainToggles,
    togglesReady: domainTogglesReady,
  } = useMultiplesFeatureToggles([
    featureToggles.pillar.consumer.id,
    featureToggles.aiChat.consumer_domain,
    featureToggles.pillar.valueCreation.id,
    featureToggles.aiChat.value_creation_domain,
  ]);

  const showClaraDomainDropdown =
    !isDomainDropdownToggleLoading && Boolean(domainDropdownToggle);
  const isConsumerPillarEnabled =
    domainTogglesReady &&
    Boolean(domainToggles[featureToggles.pillar.consumer.id]);
  const isValueCreationPillarEnabled =
    domainTogglesReady &&
    Boolean(domainToggles[featureToggles.pillar.valueCreation.id]);
  const isValueCreationDomainEnabled =
    domainTogglesReady &&
    Boolean(domainToggles[featureToggles.aiChat.value_creation_domain]);
  const isConsumerDomainEnabled =
    domainTogglesReady &&
    Boolean(domainToggles[featureToggles.aiChat.consumer_domain]);

  const availableClaraDomainOptions = useMemo(
    () =>
      CLARA_DOMAIN_OPTIONS.filter((option) => {
        if (option.value === CLARA_CONSUMER_PROJECT_KEY) {
          return isConsumerPillarEnabled && isConsumerDomainEnabled;
        }

        if (option.value === CLARA_VALUE_CREATION_PROJECT_KEY) {
          return isValueCreationPillarEnabled && isValueCreationDomainEnabled;
        }

        return true;
      }),
    [
      isConsumerDomainEnabled,
      isConsumerPillarEnabled,
      isValueCreationDomainEnabled,
      isValueCreationPillarEnabled,
    ],
  );

  return {
    showClaraDomainDropdown,
    isValueCreationPillarEnabled,
    availableClaraDomainOptions,
  };
}
